SET check_function_bodies = false;
CREATE SEQUENCE public."FailedStatsCacheRefreshes_id_seq";
REVOKE ALL ON FUNCTION public.upsert_complex_stats_cache_rows(bigint, text, boolean, jsonb) FROM anon;
REVOKE ALL ON FUNCTION public.upsert_simple_stats_cache_rows(bigint, text, boolean, jsonb) FROM anon;
CREATE TABLE public."FailedStatsCacheRefreshes" (id bigint DEFAULT nextval('public."FailedStatsCacheRefreshes_id_seq"'::regclass) NOT NULL, group_id bigint NOT NULL, cache_table text NOT NULL, temporal_unit text NOT NULL, species_id bigint, time_period date, reason text NOT NULL, details jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER SEQUENCE public."FailedStatsCacheRefreshes_id_seq" OWNED BY public."FailedStatsCacheRefreshes".id;
GRANT UPDATE ON SEQUENCE public."FailedStatsCacheRefreshes_id_seq" TO anon;
GRANT UPDATE ON SEQUENCE public."FailedStatsCacheRefreshes_id_seq" TO authenticated;
GRANT UPDATE ON SEQUENCE public."FailedStatsCacheRefreshes_id_seq" TO service_role;
COMMENT ON TABLE public."FailedStatsCacheRefreshes" IS 'Append-only dead-letter log of stats-cache refresh failures: one row per cell a refresh pass could not write. Not deduplicated — a cell that fails on every pass gets a row per pass.';
COMMENT ON COLUMN public."FailedStatsCacheRefreshes".reason IS 'Why the cell could not be written. Deliberately plain text with no CHECK constraint, so a new failure kind never needs a migration. The only value in use today is ''missing_from_metric_rpc'': the cell was present in some but not all of the stats_cache_*_metrics RPC results the refresh merges.';
COMMENT ON COLUMN public."FailedStatsCacheRefreshes".details IS 'Free-form structured context for the failure, shaped per reason. For ''missing_from_metric_rpc'': { missingFromRpc: string[] }, the RPC names whose results omitted the cell.';
ALTER TABLE public."FailedStatsCacheRefreshes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."FailedStatsCacheRefreshes" ADD CONSTRAINT "FailedStatsCacheRefreshes_pkey" PRIMARY KEY (id);
ALTER TABLE public."FailedStatsCacheRefreshes" ADD CONSTRAINT failed_stats_cache_refreshes_cache_table_check CHECK (cache_table = ANY (ARRAY['SimpleStatsCache'::text, 'ComplexStatsCache'::text]));
ALTER TABLE public."FailedStatsCacheRefreshes" ADD CONSTRAINT failed_stats_cache_refreshes_group_id_fkey FOREIGN KEY (group_id) REFERENCES public."RingingGroups"(id);
ALTER TABLE public."FailedStatsCacheRefreshes" ADD CONSTRAINT failed_stats_cache_refreshes_species_id_fkey FOREIGN KEY (species_id) REFERENCES public."Species"(id);
ALTER TABLE public."FailedStatsCacheRefreshes" ADD CONSTRAINT failed_stats_cache_refreshes_temporal_unit_check CHECK (temporal_unit = ANY (ARRAY['day'::text, 'month'::text, 'year'::text, 'month-squashed'::text, 'all-time'::text]));
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public."FailedStatsCacheRefreshes" TO anon;
GRANT INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public."FailedStatsCacheRefreshes" TO authenticated;
GRANT ALL ON public."FailedStatsCacheRefreshes" TO service_role;
CREATE INDEX idx_failed_stats_cache_refreshes_group_id ON public."FailedStatsCacheRefreshes" (group_id);
CREATE POLICY group_failed_stats_cache_refreshes_access ON public."FailedStatsCacheRefreshes" FOR SELECT USING ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
CREATE POLICY group_failed_stats_cache_refreshes_insert ON public."FailedStatsCacheRefreshes" FOR INSERT WITH CHECK ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
